import random

def generate\_puzzle():
 num1 = random.randint(1, 100)
 num2 = random.randint(1, 100)
 operator = random.choice(["+", "-"])

 if operator == "+":
 answer = num1 + num2
 else:
 answer = num1 - num2

 return f"{num1} {operator} {num2}", answer

def play\_game():
 score = 0

 while True:
 puzzle, answer = generate_puzzle()
 print("Solve this puzzle (or type 'quit' to exit):")
 print(puzzle)
 user_input = input("> ")

 if user_input.lower() == "quit":
 break

 try:
 user_answer = int(user_input)
 if user_answer == answer:
 score += 1
 print("Correct! Your score is:", score)
 else:
 print("Incorrect. The correct answer is:", answer)
 except ValueError:
 print("Invalid input. Please enter a number or type 'quit' to exit.")

 print("Thanks for playing! Your final score is:", score)

if __name__ == "\_\_main\_\_":
 play_game()
```
